\set ON_ERROR_STOP on
begin;
select set_config('test.development_fixture', :'development_fixture', true);
select test.assert((select relrowsecurity from pg_class where oid='public.development_workspaces'::regclass),'Development RLS enabled');
select test.assert(not has_table_privilege('anon','public.development_workspaces','select'),'Anonymous cannot read development');
select test.assert(not has_table_privilege('authenticated','public.development_workspaces','insert,update,delete'),'Direct plan writes denied');
select test.assert(not has_function_privilege('anon','public.load_development_workspace(uuid)','execute'),'Anonymous RPC reads denied');
select test.assert(not has_function_privilege('anon','public.save_development_workspace(uuid,bigint,jsonb,uuid)','execute'),'Anonymous RPC writes denied');
select test.assert(not has_function_privilege('authenticated','diamond_private.validate_development(uuid,jsonb,jsonb)','execute'),'Validation helper is private');
select test.assert((select bool_and(proconfig @> array['search_path=""']) from pg_proc where oid in ('public.load_development_workspace(uuid)'::regprocedure,'public.save_development_workspace(uuid,bigint,jsonb,uuid)'::regprocedure)),'Development RPC search paths fixed');
set local role authenticated;
do $$
#variable_conflict use_variable
declare
  owner_id uuid:='10000000-0000-4000-8000-000000000001';
  viewer_id uuid:='10000000-0000-4000-8000-000000000003';
  coach_id uuid:='10000000-0000-4000-8000-000000000004';
  stranger_id uuid:='10000000-0000-4000-8000-000000000002';
  team_id uuid; season_id uuid; invite jsonb; coach_invite jsonb; snapshot jsonb;
  data jsonb:=current_setting('test.development_fixture')::jsonb; changed jsonb; roster jsonb;
  mutation uuid:=gen_random_uuid(); review jsonb; version jsonb; before_ratings jsonb;
  empty_data jsonb:='{"schemaVersion":1,"plans":[],"reviews":[]}';
  shared jsonb; event_id uuid:=gen_random_uuid(); block_id uuid:=gen_random_uuid();
begin
  perform set_config('request.jwt.claim.sub',owner_id::text,true); perform public.save_profile('Development owner');
  team_id:=(public.create_team('Development test','HVLL','Minor B','Fall 2026')->>'id')::uuid;
  season_id:=((public.load_workspace(team_id)->'data'->'teams'->0)->>'seasonId')::uuid;
  data:=jsonb_set(data,'{plans,0,seasonId}',to_jsonb(season_id::text));
  snapshot:=public.load_development_workspace(team_id);
  perform test.assert(snapshot->'data'=empty_data and snapshot->'revision'='0'::jsonb,'New development workspace empty without creating a row');
  invite:=public.create_team_invite(team_id,'viewer'); coach_invite:=public.create_team_invite(team_id,'coach');
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,data,mutation),'22023');
  roster:=jsonb_build_object('schemaVersion',1,'players',jsonb_build_array(jsonb_build_object('id',data->'plans'->0->>'playerId','name','Synthetic development player','number','2','age',7,'positions','','notes','','archived',false,'draftStatus','available')),'sessions','[]'::jsonb,'evaluations','[]'::jsonb,'goals','[]'::jsonb);
  perform public.save_scouting_workspace(team_id,0,roster,gen_random_uuid()); before_ratings:=public.load_scouting_workspace(team_id);
  changed:=data||'{"ratings":{}}';
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  changed:=jsonb_set(data,'{plans,0,versions,0,home,ratings}','{}');
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  changed:=jsonb_set(data,'{plans,0,versions,0,followUpDate}','"2026-02-30"');
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  changed:=jsonb_set(data,'{plans,0,versions,0,home,minAge}','8');
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  changed:=jsonb_set(data,'{plans,0,createdBy}',to_jsonb(coach_id::text));
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  changed:=jsonb_set(data,'{plans,0,versions,0,createdBy}',to_jsonb(coach_id::text));
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  changed:=jsonb_set(data,'{plans,0,versions,0,practiceBlockId}',to_jsonb(block_id::text));
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  changed:=jsonb_set(data,'{plans,0,versions,0,status}','"closed"');
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,changed,mutation),'22023');
  snapshot:=public.save_development_workspace(team_id,0,data,mutation);
  perform test.assert(snapshot->'revision'='1'::jsonb and snapshot->'data'=data,'Valid first plan saved');
  perform test.assert(public.save_development_workspace(team_id,0,data,mutation)=snapshot,'Same request retries idempotently');
  perform test.rejects(format('select public.save_development_workspace(%L,0,%L::jsonb,%L)',team_id,data,gen_random_uuid()),'40001');
  perform test.rejects(format('select public.save_development_workspace(%L,1,%L::jsonb,%L)',team_id,empty_data,gen_random_uuid()),'22023');
  changed:=jsonb_set(data,'{plans,0,versions,0,goal}','"Rewritten history"');
  perform test.rejects(format('select public.save_development_workspace(%L,1,%L::jsonb,%L)',team_id,changed,gen_random_uuid()),'22023');
  perform test.assert(public.load_scouting_workspace(team_id)=before_ratings,'Creating plan leaves scouting and ratings unchanged');
  perform test.assert(not ((public.load_workspace(team_id)->'data') ? 'plans'),'Personal plans absent from shared team payload');

  perform set_config('request.jwt.claim.sub',viewer_id::text,true); perform public.save_profile('Development viewer'); perform public.join_team(invite->>'code');
  perform test.assert((select count(*)=0 from public.development_workspaces),'Viewer cannot select populated plans');
  perform test.rejects(format('select public.load_development_workspace(%L)',team_id),'42501');
  perform test.rejects(format('select public.save_development_workspace(%L,1,%L::jsonb,%L)',team_id,data,gen_random_uuid()),'42501');
  perform set_config('request.jwt.claim.sub',stranger_id::text,true); perform public.save_profile('Other household');
  perform public.create_team('Other development team','HVLL','Minor B','Fall 2026');
  perform test.assert((select count(*)=0 from public.development_workspaces),'Other team owner cannot select plans');
  perform test.rejects(format('select public.load_development_workspace(%L)',team_id),'42501');
  perform test.rejects(format('select public.save_development_workspace(%L,1,%L::jsonb,%L)',team_id,data,gen_random_uuid()),'42501');

  perform set_config('request.jwt.claim.sub',coach_id::text,true); perform public.save_profile('Development assistant'); perform public.join_team(coach_invite->>'code');
  perform test.assert(public.load_development_workspace(team_id)->'data'=data,'Assistant can read team development plans');
  version:=data->'plans'->0->'versions'->0||jsonb_build_object('version',2,'createdBy',coach_id,'createdAt','2026-10-03T18:00:00Z','goal','A revised achievable goal.');
  changed:=jsonb_set(data,'{plans,0,versions}',data->'plans'->0->'versions'||jsonb_build_array(version));
  review:=jsonb_build_object('id',gen_random_uuid(),'planId',data->'plans'->0->>'id','version',1,'createdBy',coach_id,'createdAt','2026-10-03T18:10:00Z','outcome','needs-help','reflection','Family requested an easier game.','coachNotes','Synthetic follow-up');
  changed:=jsonb_set(changed,'{reviews}',jsonb_build_array(review));
  snapshot:=public.save_development_workspace(team_id,1,changed,gen_random_uuid()); data:=changed;
  perform test.assert(snapshot->'revision'='2'::jsonb and snapshot->'data'->'plans'->0->'versions'->0->>'goal'='Gather my feet in balance.','Assistant appends version and retains original');
  changed:=jsonb_set(data,'{reviews,0,coachNotes}','"Changed follow-up"');
  perform test.rejects(format('select public.save_development_workspace(%L,2,%L::jsonb,%L)',team_id,changed,gen_random_uuid()),'22023');
  changed:=jsonb_set(data,'{reviews}','[]');
  perform test.rejects(format('select public.save_development_workspace(%L,2,%L::jsonb,%L)',team_id,changed,gen_random_uuid()),'22023');

  perform set_config('request.jwt.claim.sub',owner_id::text,true);
  shared:=public.load_workspace(team_id);
  changed:=shared->'data';
  changed:=jsonb_set(changed,'{events}',jsonb_build_array(jsonb_build_object('id',event_id,'teamId',team_id,'seasonId',season_id,'type','practice','title','Synthetic practice','date','2026-10-09','startTime','16:00','endTime','17:00','timeZone','America/Los_Angeles','location','Test field','notes','','status','scheduled')));
  changed:=jsonb_set(changed,'{activities}',jsonb_build_array(jsonb_build_object('id',block_id,'teamId',team_id,'seasonId',season_id,'eventId',event_id,'playerId',data->'plans'->0->>'playerId','playerName','Synthetic development player','title','Approved test drill','objective','Test balance','measure','Controlled finish','minutes',8,'completed',false)));
  perform public.save_workspace(team_id,(shared->>'revision')::bigint,changed,gen_random_uuid());
  version:=data->'plans'->0->'versions'->1||jsonb_build_object('version',3,'createdBy',owner_id,'createdAt','2026-10-04T18:00:00Z','practiceBlockId',block_id);
  data:=jsonb_set(data,'{plans,0,versions}',data->'plans'->0->'versions'||jsonb_build_array(version));
  snapshot:=public.save_development_workspace(team_id,2,data,gen_random_uuid());
  perform test.assert(snapshot->'revision'='3'::jsonb,'Owner links an approved same-team player block');
  version:=version||jsonb_build_object('version',4,'status','closed','createdAt','2026-10-05T18:00:00Z');
  data:=jsonb_set(data,'{plans,0,versions}',data->'plans'->0->'versions'||jsonb_build_array(version));
  perform public.save_development_workspace(team_id,3,data,gen_random_uuid());
  perform test.assert(public.load_scouting_workspace(team_id)=before_ratings,'Versions, links, follow-ups and closure leave ratings unchanged');
  perform public.remove_team_member(team_id,coach_id);
  perform set_config('request.jwt.claim.sub',coach_id::text,true);
  perform test.assert((select count(*)=0 from public.development_workspaces),'Removed coach loses direct plan access');
  perform test.rejects(format('select public.load_development_workspace(%L)',team_id),'42501');
  perform test.rejects(format('select public.save_development_workspace(%L,4,%L::jsonb,%L)',team_id,data,gen_random_uuid()),'42501');
  perform set_config('request.jwt.claim.sub','',true);
  perform test.rejects(format('select public.load_development_workspace(%L)',team_id),'42501');
  raise notice 'Passed: development isolation, snapshots, authorship, age/link fit, immutable history, ratings separation, retry and revision conflicts.';
end $$;
rollback;
